import{_ as t,c as r,o as a,ag as i}from"./chunks/framework.CQuhCYrb.js";const g=JSON.parse('{"title":"Certifications & Learning","description":"","frontmatter":{"title":"Certifications & Learning"},"headers":[],"relativePath":"general/certifications-and-learning.md","filePath":"general/certifications-and-learning.md","lastUpdated":null}'),o={name:"general/certifications-and-learning.md"};function n(s,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="certifications-learning" tabindex="-1">Certifications &amp; Learning <a class="header-anchor" href="#certifications-learning" aria-label="Permalink to &quot;Certifications &amp; Learning&quot;">​</a></h1><p>Military credentialing programs, certification guides, free learning resources, and professional development opportunities for service members and veterans.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Description</th></tr></thead><tbody><tr><td><a href="/general/learning.html">Learning Resources</a></td><td>Free courses, platforms, and educational programs</td></tr><tr><td><a href="/general/certifications.html">Certifications Guide</a></td><td>Certification pathways by domain</td></tr><tr><td><a href="/general/funding-certifications-through-the-military.html">Funding Certifications</a></td><td>Military funding options</td></tr></tbody></table><h2 id="military-funding-programs" tabindex="-1">Military Funding Programs <a class="header-anchor" href="#military-funding-programs" aria-label="Permalink to &quot;Military Funding Programs&quot;">​</a></h2><h3 id="credentialing-assistance-ca" tabindex="-1">Credentialing Assistance (CA) <a class="header-anchor" href="#credentialing-assistance-ca" aria-label="Permalink to &quot;Credentialing Assistance (CA)&quot;">​</a></h3><ul><li><strong>Amount</strong>: $4,000/year</li><li><strong>Purpose</strong>: Professional certifications aligned with career goals</li><li><strong>Portal</strong>: <a href="https://www.armyignited.com/app/" target="_blank" rel="noreferrer">ArmyIgnitED</a></li><li><strong>Guide</strong>: <a href="/general/credentialing-assistance.html">Credentialing Assistance</a></li></ul><h3 id="sof-education-program-sep" tabindex="-1">SOF Education Program (SEP) <a class="header-anchor" href="#sof-education-program-sep" aria-label="Permalink to &quot;SOF Education Program (SEP)&quot;">​</a></h3><ul><li><strong>Amount</strong>: Up to $10,000/year</li><li><strong>Purpose</strong>: Individual knowledge gaps in special operations roles</li><li><strong>Separate from</strong>: TA and CA (additional funding)</li><li><strong>Requirements</strong>: SF-182, no planned separation within 18 months</li><li><strong>Guide</strong>: <a href="https://u.pcloud.link/publink/show?code=XZ0frk0ZchOJr4ELEVkiFyB7Ic45CmhSpaEk" target="_blank" rel="noreferrer">SEP Funds Guide</a></li></ul><h3 id="tuition-assistance-ta" tabindex="-1">Tuition Assistance (TA) <a class="header-anchor" href="#tuition-assistance-ta" aria-label="Permalink to &quot;Tuition Assistance (TA)&quot;">​</a></h3><ul><li><strong>Amount</strong>: Varies by service</li><li><strong>Purpose</strong>: Degree programs and education</li><li><strong>Note</strong>: Separate from CA funding</li></ul><h2 id="discounted-certifications" tabindex="-1">Discounted Certifications <a class="header-anchor" href="#discounted-certifications" aria-label="Permalink to &quot;Discounted Certifications&quot;">​</a></h2><h3 id="pearson-vue-government-store" tabindex="-1">Pearson VUE Government Store <a class="header-anchor" href="#pearson-vue-government-store" aria-label="Permalink to &quot;Pearson VUE Government Store&quot;">​</a></h3><p><a href="https://govstore.pearsonvue.com/" target="_blank" rel="noreferrer">Pearson VUE Government Store</a> - Discounted certification exams</p><table tabindex="0"><thead><tr><th>Vendor</th><th>Link</th></tr></thead><tbody><tr><td>AWS</td><td><a href="https://govstore.pearsonvue.com/shop/aws" target="_blank" rel="noreferrer">AWS Certification</a></td></tr><tr><td>CompTIA</td><td><a href="https://govstore.pearsonvue.com/shop/comptia" target="_blank" rel="noreferrer">CompTIA Certification</a></td></tr><tr><td>Microsoft</td><td><a href="https://govstore.pearsonvue.com/shop/microsoft" target="_blank" rel="noreferrer">Microsoft Certification</a></td></tr><tr><td>Cisco</td><td><a href="https://govstore.pearsonvue.com/shop/cisco" target="_blank" rel="noreferrer">Cisco Certification</a></td></tr></tbody></table><h2 id="certifications-by-domain" tabindex="-1">Certifications by Domain <a class="header-anchor" href="#certifications-by-domain" aria-label="Permalink to &quot;Certifications by Domain&quot;">​</a></h2><h3 id="cybersecurity" tabindex="-1">Cybersecurity <a class="header-anchor" href="#cybersecurity" aria-label="Permalink to &quot;Cybersecurity&quot;">​</a></h3><p><strong>SANS/GIAC</strong></p><ul><li><a href="/general/credentialing-assistance.html">Credentialing Assistance for SANS</a> - Use CA for $4k SANS training</li><li><a href="https://www.sans.org/cyber-security-skills-roadmap/" target="_blank" rel="noreferrer">SANS Roadmap</a> - Career progression</li><li>Recommended: <a href="https://www.sans.org/cyber-security-courses/hacker-techniques-incident-handling/" target="_blank" rel="noreferrer">SEC504 GCIH</a></li></ul><p><strong>Offensive Security</strong></p><ul><li><a href="/cybersecurity/oscp.html">OSCP</a> - Penetration Testing with Kali Linux</li><li><a href="/general/advanced-web-attacks-and-exploitation-oswe.html">OSWE</a> - Advanced Web Attacks</li></ul><p><strong>GIAC Certifications</strong></p><ul><li><a href="/cybersecurity/gpen.html">GPEN</a> - Penetration Tester</li><li><a href="/general/gwapt.html">GWAPT</a> - Web Application Penetration Tester</li></ul><p><strong>CompTIA</strong></p><ul><li><a href="/general/casp.html">CASP+ (CAS-004)</a> - Advanced Security Practitioner</li></ul><p><strong>Free</strong></p><ul><li><a href="https://www.isc2.org/Certifications/CC" target="_blank" rel="noreferrer">ISC2 CC</a> - Free entry-level certification</li></ul><h3 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h3><ul><li><a href="/general/computer-network-operations-cno.html">CNO</a> - Computer Network Operations</li><li><a href="https://www.ccna.ninja/" target="_blank" rel="noreferrer">CCNA Ninja</a> - Free NetAcad training with voucher opportunity</li></ul><h3 id="rf-ew" tabindex="-1">RF/EW <a class="header-anchor" href="#rf-ew" aria-label="Permalink to &quot;RF/EW&quot;">​</a></h3><ul><li><a href="/radio/ham-radio.html">HAM Radio</a> - Amateur radio licensing</li><li><a href="https://www.ieee.org/education/continuing-education.html" target="_blank" rel="noreferrer">IEEE Continuing Education</a></li></ul><h2 id="free-learning-resources" tabindex="-1">Free Learning Resources <a class="header-anchor" href="#free-learning-resources" aria-label="Permalink to &quot;Free Learning Resources&quot;">​</a></h2><h3 id="military-specific-platforms" tabindex="-1">Military-Specific Platforms <a class="header-anchor" href="#military-specific-platforms" aria-label="Permalink to &quot;Military-Specific Platforms&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Platform</th><th>Access</th><th>Description</th></tr></thead><tbody><tr><td><a href="https://digitalu.af.mil/" target="_blank" rel="noreferrer">Udemy for Military</a></td><td>.mil email</td><td>Free courses</td></tr><tr><td><a href="https://www.oreilly.com/self-registration/dod-mwr-libraries-army/" target="_blank" rel="noreferrer">O&#39;Reilly</a></td><td>MWR Libraries</td><td>Technical books and videos</td></tr><tr><td><a href="https://www.dcita.edu/" target="_blank" rel="noreferrer">DC3 Cyber Training</a></td><td>DoD</td><td>Forensics and cyber fundamentals</td></tr><tr><td><a href="https://usarmy.percipio.com/" target="_blank" rel="noreferrer">Army eLearning</a></td><td>Army</td><td>CompTIA prep and more</td></tr></tbody></table><h3 id="university-programs" tabindex="-1">University Programs <a class="header-anchor" href="#university-programs" aria-label="Permalink to &quot;University Programs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Institution</th><th>Link</th><th>Notes</th></tr></thead><tbody><tr><td>Harvard</td><td><a href="https://pll.harvard.edu/catalog/free" target="_blank" rel="noreferrer">Free Courses</a></td><td>Tech, policy, AI/ML, business</td></tr><tr><td>MIT</td><td><a href="https://ocw.mit.edu/about/" target="_blank" rel="noreferrer">OpenCourseWare</a></td><td>Full course materials</td></tr><tr><td>Coursera</td><td><a href="https://www.eventbrite.com/e/no-cost-on-line-coursera-certification-courses-for-military-and-spouse-tickets-165655358637" target="_blank" rel="noreferrer">Military Program</a></td><td>Free certifications</td></tr></tbody></table><h3 id="other-resources" tabindex="-1">Other Resources <a class="header-anchor" href="#other-resources" aria-label="Permalink to &quot;Other Resources&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Resource</th><th>Link</th><th>Description</th></tr></thead><tbody><tr><td>Microsoft ESI</td><td><a href="https://esi.microsoft.com/" target="_blank" rel="noreferrer">Enterprise Skills</a></td><td>Microsoft training</td></tr><tr><td>PACKT</td><td><a href="https://www.packtpub.com/free-learning" target="_blank" rel="noreferrer">Free Learning</a></td><td>Daily free tech books</td></tr><tr><td>Tutor.com</td><td><a href="http://military.tutor.com/" target="_blank" rel="noreferrer">Military</a></td><td>Free tutoring for families</td></tr><tr><td>AI Tutor</td><td><a href="https://llamatutor.together.ai" target="_blank" rel="noreferrer">LlamaTutor</a></td><td>AI-powered learning</td></tr></tbody></table><h2 id="defense-acquisition-university-dau" tabindex="-1">Defense Acquisition University (DAU) <a class="header-anchor" href="#defense-acquisition-university-dau" aria-label="Permalink to &quot;Defense Acquisition University (DAU)&quot;">​</a></h2><p><a href="https://www.dau.edu" target="_blank" rel="noreferrer">DAU</a> provides courses counting as military education with professional certifications.</p><h3 id="notable-courses" tabindex="-1">Notable Courses <a class="header-anchor" href="#notable-courses" aria-label="Permalink to &quot;Notable Courses&quot;">​</a></h3><ul><li><strong>ACQ101</strong> - Acquisitions 101: Foundational acquisition knowledge</li><li><strong>Source Selection</strong> - Ethics and evaluation techniques</li><li><strong>ETM 3150</strong> - Introduction to Emerging Technology</li></ul><h3 id="dau-credentials" tabindex="-1">DAU Credentials <a class="header-anchor" href="#dau-credentials" aria-label="Permalink to &quot;DAU Credentials&quot;">​</a></h3><ul><li><a href="https://www.dau.edu/credentials" target="_blank" rel="noreferrer">Small Business Program Credential</a></li><li>Fulfills continuing education for PMP and other certifications</li></ul><h2 id="cheat-sheets-study-resources" tabindex="-1">Cheat Sheets &amp; Study Resources <a class="header-anchor" href="#cheat-sheets-study-resources" aria-label="Permalink to &quot;Cheat Sheets &amp; Study Resources&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Link</th></tr></thead><tbody><tr><td>OWASP Cheat Sheets</td><td><a href="https://cheatsheetseries.owasp.org/" target="_blank" rel="noreferrer">cheatsheetseries.owasp.org</a></td></tr><tr><td>Bug Bounty Writeups</td><td><a href="https://github.com/devanshbatham/Awesome-Bugbounty-Writeups" target="_blank" rel="noreferrer">GitHub Collection</a></td></tr><tr><td>OSCP Resources</td><td><a href="https://github.com/0xsyr0/OSCP" target="_blank" rel="noreferrer">GitHub Collection</a></td></tr></tbody></table><h2 id="comptia-token-process" tabindex="-1">CompTIA Token Process <a class="header-anchor" href="#comptia-token-process" aria-label="Permalink to &quot;CompTIA Token Process&quot;">​</a></h2><ol><li>Complete training on <a href="https://usarmy.percipio.com/" target="_blank" rel="noreferrer">Army eLearning</a></li><li>Navigate to ACTMS website</li><li>Upload cyber awareness certificates</li><li>Submit token request (bottom of page)</li><li>Receive voucher code for exam</li></ol><p><strong>Note</strong>: Processing can take up to 6 months - plan accordingly.</p><h2 id="community-resources" tabindex="-1">Community Resources <a class="header-anchor" href="#community-resources" aria-label="Permalink to &quot;Community Resources&quot;">​</a></h2><ul><li><a href="https://forum.irregularchat.com/t/community-links-to-chats-and-services/229#p-598-tech-8" target="_blank" rel="noreferrer">Tech Signal Group</a> - Certification discussions</li><li><a href="https://forum.irregularchat.com/tag/learning" target="_blank" rel="noreferrer">Learning Discussions</a> - Community posts</li></ul><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="/general/military-and-career.html">Military &amp; Career</a> - Transition and career resources</li><li><a href="/cybersecurity/">Cybersecurity</a> - Security guides and tools</li><li><a href="/ai-ml/">AI &amp; Autonomy</a> - AI/ML learning resources</li></ul>',53)])])}const f=t(o,[["render",n]]);export{g as __pageData,f as default};
